import{z as s,x as o,o as B,c as n,q as A,j as t,D as a,d as l,s as i,S as r}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"内存预算的完整清单","description":"","frontmatter":{"title":"内存预算的完整清单","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/dist-memory-budget.md","filePath":"llm/dist-memory-budget.md","lastUpdated":1791063341000}'),d={name:"llm/dist-memory-budget.md"};function p(D,E,m,C,h,F){const e=o("Mermaid");return B(),n("div",null,[E[2]||(E[2]=A('<h1 id="内存预算的完整清单" tabindex="-1">内存预算的完整清单 <a class="header-anchor" href="#内存预算的完整清单" aria-label="Permalink to &quot;内存预算的完整清单&quot;">​</a></h1><div class="epigraph"><p>显存爆在峰值而不是总和；预算清单要按「什么时刻、谁还活着」记账，不按配置项罗列。</p><footer>—— 据 Rajbhandari 等 ZeRO 系列与 Korthikanti 等 2022 的显存分析整理</footer></div><p><a href="/llm/dist-mfu-case">上一课</a>管的是时间账；本课管空间账。前面分别切了参数侧（ZeRO 课）与激活侧（重计算课），本课把一次 step 的全部内存项合成一张完整清单：每一项多大、在哪个时刻活着、被哪个旋钮影响。清单的用途是预算——在开跑之前判断配置会不会 OOM。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>OOM 的三项高频根因都不在参数：峰值激活（微批数乘序列长）、瞬时缓冲（某层权重被聚集齐的一瞬、梯度桶将满的一瞬）、以及公式外的固定项（通信库缓冲、CUDA 上下文、框架 workspace、碎片）。逐项清单缺失时，调显存变成盲试：关一个重计算、降一档序列长，撞运气。第二类错是把持久账当峰值账：\\(16\\Phi/N\\) 算出来放得下，跑起来在反传开始那一瞬爆掉——那一瞬检查点重放、整层聚集权重、梯度桶三者叠加。</p><p><span class="marginnote">瞬时缓冲可以想象成厨房高峰期的料理台：食材平时放在仓库（常驻显存），但出菜那一瞬必须全部摆上台面——台面（峰值显存）不够，仓库再大也得停摆。</span></p>',6)),(B(),t(r,null,{default:a(()=>[i(e,{id:"mermaid-16",class:"mermaid",graph:"flowchart%20LR%0A%20%20F%5B%22%E5%89%8D%E5%90%91%3A%20%E6%BF%80%E6%B4%BB%E9%80%90%E5%B1%82%E7%B4%AF%E7%A7%AF%22%5D%20--%3E%20RP%5B%22%E6%A3%80%E6%9F%A5%E7%82%B9%E6%AE%B5%E8%A7%A6%E5%8F%91%E9%87%8D%E6%94%BE%3A%20%E6%95%B4%E6%AE%B5%E6%BF%80%E6%B4%BB%E9%87%8D%E5%BB%BA%22%5D%0A%20%20AG%5B%22ZeRO%20All-Gather%3A%20%E6%8A%AC%E8%B5%B7%E5%BD%93%E5%89%8D%E6%95%B4%E5%B1%82%E6%9D%83%E9%87%8D%22%5D%20--%3E%20PK%0A%20%20BK%5B%22%E4%B8%8A%E4%B8%80%E6%AE%B5%E5%8F%8D%E5%90%91%3A%20%E6%A2%AF%E5%BA%A6%E6%AD%A3%E5%9C%A8%E8%BF%9B%E6%A1%B6%22%5D%20--%3E%20PK%0A%20%20RP%20--%3E%20PK%5B%22%E5%8F%8D%E4%BC%A0%E5%BC%80%E5%A7%8B%E4%B8%80%E7%9E%AC%3A%20%E4%B8%89%E9%A1%B9%E7%9E%AC%E6%97%B6%E5%8F%A0%E5%8A%A0%2C%20%E5%B3%B0%E5%80%BC%E5%9C%A8%E8%BF%99%22%5D%0A%20%20PK%20--%3E%20BP%5B%22%E5%8F%8D%E4%BC%A0%E4%B8%BB%E4%BD%93%3A%20%E7%9E%AC%E6%97%B6%E9%A1%B9%E9%80%90%E6%AE%B5%E6%B6%88%E9%80%80%22%5D%0A%20%20BP%20--%3E%20ST%5B%22%E6%AD%A5%E6%9C%AB%3A%20%E5%8F%AA%E5%89%A9%E6%8C%81%E4%B9%85%E6%A0%8F%E5%B8%B8%E9%A9%BB%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[l(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A('<h3 id="两栏清单" tabindex="-1">两栏清单 <a class="header-anchor" href="#两栏清单" aria-label="Permalink to &quot;两栏清单&quot;">​</a></h3><p>持久栏：参数（\\(\\Phi\\) 乘精度字节数）、梯度（同阶，注意 FP32 累积会翻倍）、优化器状态（Adam 按 \\(12\\Phi/N\\) 分片）。瞬时栏：激活——层数、微批、序列长与每层系数的乘积，重计算把「层数」换成「检查点段间隔」；当前层聚集权重——ZeRO 三档每层 All-Gather 抬起的整层（或 TP 分片后的）参数；梯度桶——通信缓冲，随桶大小与 dtype 变；大词表 logits——词表乘批乘序列的 fp32 softmax 中间量，长序列下经常超过激活本体。固定栏：CUDA 上下文每卡数百 MB 级、cuDNN workspace、NCCL 通道缓冲、碎片水位（按实测预留一成量级）。</p><p><span class="marginnote">拿 7B 模型代一下持久栏：fp16 参数约 14 GB、梯度约 14 GB，Adam 状态按 \\(12\\Phi/N\\) 分片到 8 卡每卡约 10.5 GB——持久栏合计每卡 38 GB 上下，还没算激活与固定项。80 GB 的卡看着宽裕，实际一步不慎就爆。</span></p><p><span class="marginnote">大词表 logits 是清单里最常漏的一项：\\(V\\) 乘 \\(b\\) 乘 \\(s\\) 的 fp32 中间量在五万词表、长序列下轻松超过全部激活。切分 softmax 或流式算 loss 前，先把它从「激活」里单列出来，否则重计算调半天找错了门。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>清单的用法是矩阵：行是内存项，列是旋钮（TP、PP、ZeRO 档、重计算粒度、微批、序列长、桶与 dtype、卸载），每格标方向与量级——比如重计算行只作用于激活行，ZeRO 三档作用于参数与优化器行但抬高瞬时栏的聚集项，桶大小作用于梯度缓冲行。建表一次、标定一次（用自己框架的实际系数，不抄论文常数），以后新配置先过表再开跑。实测对账用框架的内存快照：把峰值时刻对齐到具体行号，确认爆的是清单里哪一项，再动对应旋钮——顺序是「先定位后拧」，与 MFU 课的分解同构。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么峰值出现在反传开始：检查点重放把检查点之间的激活整段重建，同时上一段反向的梯度正在进桶，ZeRO 三档还在为当前层抬权重——三个瞬时项在同一时刻相加，这就是「总和放得下、峰值爆」的机制。为什么碎片能杀死「够用」的配置：分配与释放的模式是周期性的，周期性分配在内存里锯出洞，总空闲够、连续块不够；缓解靠分段分配与虚拟内存手段，预算上把碎片水位当固定项预留。卸载时账本要跨设备合：CPU 侧的 pinned 内存与 NVMe 带宽进同一张表，PCIe 的搬运时间同时是内存账与时间账的项。</p><p><span class="marginnote">初学者容易把碎片当成「显存不够」的同义词：其实总空闲是够的，只是连续块不够——像停车场总空位够、但零散在角落，一辆大卡车停不进去。预算里预留一成碎片水位，就是把这件事制度化。</span></p>',9)),(B(),t(r,null,{default:a(()=>[i(e,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20BUDGET%5B%22%E9%A2%84%E7%AE%97%E8%A1%A8%3A%20%E8%A1%8C%E4%B8%BA%E5%86%85%E5%AD%98%E9%A1%B9%2C%20%E5%88%97%E4%B8%BA%E6%97%8B%E9%92%AE%22%5D%20--%3E%20PERSIST%5B%22%E6%8C%81%E4%B9%85%3A%20%E5%8F%82%E6%95%B0%20%2F%20%E6%A2%AF%E5%BA%A6%20%2F%20%E4%BC%98%E5%8C%96%E5%99%A8%E5%88%86%E7%89%87%22%5D%0A%20%20BUDGET%20--%3E%20TRANS%5B%22%E7%9E%AC%E6%97%B6%3A%20%E6%BF%80%E6%B4%BB%20%2F%20%E8%81%9A%E9%9B%86%E6%9D%83%E9%87%8D%20%2F%20%E6%A2%AF%E5%BA%A6%E6%A1%B6%20%2F%20logits%22%5D%0A%20%20BUDGET%20--%3E%20FIX%5B%22%E5%9B%BA%E5%AE%9A%3A%20%E4%B8%8A%E4%B8%8B%E6%96%87%20%2F%20workspace%20%2F%20NCCL%20%2F%20%E7%A2%8E%E7%89%87%E6%B0%B4%E4%BD%8D%22%5D%0A%20%20PERSIST%20--%3E%20PEAK%5B%22%E5%B3%B0%E5%80%BC%20%3D%20%E5%8F%8D%E4%BC%A0%E5%BC%80%E5%A7%8B%E4%B8%80%E7%9E%AC%3A%20%E9%87%8D%E6%94%BE%20%2B%20%E8%BF%9B%E6%A1%B6%20%2B%20%E8%81%9A%E9%9B%86%22%5D%0A%20%20TRANS%20--%3E%20PEAK%0A%20%20FIX%20--%3E%20PEAK%0A%20%20PEAK%20--%3E%20VERIFY%7B%22%E5%86%85%E5%AD%98%E5%BF%AB%E7%85%A7%E5%AF%B9%E4%B8%8A%E6%B8%85%E5%8D%95%3F%22%7D%0A%20%20VERIFY%20--%3E%7C%E5%AF%B9%E4%B8%8A%7C%20TUNE%5B%22%E5%8A%A8%E5%AF%B9%E5%BA%94%E6%97%8B%E9%92%AE%2C%20%E9%87%8D%E7%AE%97%E9%A2%84%E7%AE%97%22%5D%0A%20%20VERIFY%20--%3E%7C%E5%AF%B9%E4%B8%8D%E4%B8%8A%7C%20LOC%5B%22%E5%B3%B0%E5%80%BC%E5%AF%B9%E9%BD%90%E5%88%B0%E8%A1%8C%E5%8F%B7%2C%20%E6%89%BE%E6%BC%8F%E9%A1%B9%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[l(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=A('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课给静态账：运行时的水位告警与 OOM 回退是服务化课题。激活系数随实现与精度策略变，用自己栈的快照标定，不通用。清单不含 host 侧的常规内存，除非开了卸载。与时间账的交点只有两处：桶大小与卸载带宽——它们同时出现在两张表里，改任何一个要两张表一起复算。预算表是文档资产：换框架、换精度、换并行配置时增量维护，不推倒重写。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>清单分三栏：持久（参数、梯度、优化器分片）、瞬时（激活、聚集权重、梯度桶、大词表 logits）、固定（上下文、缓冲、碎片水位）。</li><li>峰值在反传开始：重放、进桶、聚集三瞬时项相加，\\(16\\Phi/N\\) 管不住它。</li><li>用「项乘旋钮」的矩阵做预算，系数用自己框架标定一次，长期复用。</li><li>实测对账用内存快照把峰值对齐到行号，先定位后拧旋钮。</li><li>出处：Rajbhandari 等，ZeRO 系列；Korthikanti 等 2022 的激活显存分析；口径与各档公式见本课程 ZeRO 与重计算两课。</li></ul>',4))])}const c=s(d,[["render",p]]);export{_ as __pageData,c as default};
